CREATE OR REPLACE FUNCTION public.wallet_guard_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists(select 1 from public.wallet_reconciliations) then
    if tg_op <> 'UPDATE' then raise exception 'Thiết lập số dư đầu kỳ đã khóa sau đối soát.'; end if;
    if new.id is distinct from old.id or new.opening_balance_cash is distinct from old.opening_balance_cash
      or new.opening_balance_bank is distinct from old.opening_balance_bank
      or new.opening_balance_date is distinct from old.opening_balance_date then
      raise exception 'Không được thay đổi số dư đầu kỳ sau đối soát.';
    end if;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_pwa_investment_receipt_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.id like 'pwa-investment-%' and old.category='investment_transfer' then
    raise exception 'Chứng từ đầu tư PWA được lưu theo phiên bản. Hoàn tác trong danh mục đầu tư, không sửa/xóa riêng chứng từ Ví.' using errcode='22023';
  end if;
  return case when tg_op='DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.contract_capture_usage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r jsonb; cid text; room_key text; tenant_key text; used boolean;
begin
 for r in select value from jsonb_array_elements(case when tg_op='UPDATE' and tg_table_name<>'rooms' then jsonb_build_array(to_jsonb(old),to_jsonb(new)) when tg_op='DELETE' then jsonb_build_array(to_jsonb(old)) else jsonb_build_array(to_jsonb(new)) end) loop
 room_key:=r->>'room_id'; tenant_key:=r->>'tenant_id';
 used:=case tg_table_name
  when 'invoices' then coalesce((r->>'paid_amount')::numeric,0)>0 or coalesce((r->>'deposit_applied')::numeric,0)>0 or coalesce(nullif(r->'payment_records','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb or r->>'payment_date' is not null or coalesce((r->>'electric_usage')::numeric,0)>0 or coalesce((r->>'water_usage')::numeric,0)>0
  when 'move_in_receipts' then r->>'payment_status'='paid' or r->>'payment_date' is not null
  when 'cash_transactions' then coalesce((r->>'amount')::numeric,0)<>0
  when 'payment_events' then coalesce((r->>'amount')::numeric,0)<>0
  when 'asset_snapshots' then true
  when 'rooms' then (r->'electric_old',r->'electric_new',r->'water_old',r->'water_new') is distinct from (to_jsonb(old)->'electric_old',to_jsonb(old)->'electric_new',to_jsonb(old)->'water_old',to_jsonb(old)->'water_new')
  else true end;
 if tg_table_name='rooms' then room_key:=r->>'id'; end if;
 if tg_table_name='payment_events' then select room_id,tenant_id into room_key,tenant_key from invoices where id=r->>'invoice_id'; end if;
 -- Reject stale operations that acquire a table lock after cancellation commits.
 if tg_op<>'DELETE' and (tg_op='INSERT' or used) and
  (exists(select 1 from contracts where id=r->>'contract_id' and status='cancelled') or
   tenant_key is not null and room_key is not null and not exists(select 1 from contracts where room_id=room_key and tenant_id=tenant_key and status='active') and
   (select status='cancelled' from contracts where room_id=room_key and tenant_id=tenant_key order by created_at desc,id desc limit 1)) then
  raise exception 'Hợp đồng đã hủy. Không được ghi thêm thanh toán, hóa đơn hoặc bàn giao cho hợp đồng này.';
 end if;
 if used then
  for cid in select c.id from contracts c where c.status='active' and c.original_confirmed_at is not null and
   (c.id=r->>'contract_id' or c.room_id=room_key and (tenant_key is null or c.tenant_id=tenant_key)) loop
   insert into contract_usage_evidence(contract_id,source_table,source_id) values(cid,tg_table_name,r->>'id') on conflict do nothing;
  end loop;
 end if;
 end loop;
 if tg_op='DELETE' then return old; else return new; end if;
end $function$

CREATE OR REPLACE FUNCTION public.wallet_guard_cash()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare checkpoint public.wallet_reconciliations%rowtype; valid_transfer boolean;
begin
  select * into checkpoint from public.wallet_reconciliations limit 1;
  if tg_op <> 'INSERT' and checkpoint.id is not null and ('cash-' || old.id) = any(checkpoint.entry_ids) then
    raise exception 'Giao dịch trước mốc đối soát đã khóa. Không được sửa/xóa lịch sử.';
  end if;
  if tg_op <> 'INSERT' and old.category = 'wallet_transfer' then
    raise exception 'Hai phần chuyển ví được ghi cùng nhau, không được sửa/xóa riêng một phần.';
  end if;
  if tg_op <> 'DELETE' then
    if new.type not in ('income', 'expense') or new.type is null or new.amount is null or new.amount <= 0
      or new.payment_method is null or new.payment_method not in ('cash', 'transfer') then
      raise exception 'Giao dịch phải có số tiền dương và một ví thanh toán hợp lệ.';
    end if;
    if tg_op = 'UPDATE' and new.id is distinct from old.id then raise exception 'Không được đổi mã giao dịch.'; end if;
    if new.category = 'wallet_transfer' then
      select exists(select 1 from public.wallet_transfer_requests r where r.amount = new.amount and (
        (new.id = 'wallet-out-' || r.id and new.type = 'expense' and new.payment_method = r.source)
        or (new.id = 'wallet-in-' || r.id and new.type = 'income' and new.payment_method = case when r.source = 'cash' then 'transfer' else 'cash' end)
      )) into valid_transfer;
      if not valid_transfer then raise exception 'Phải dùng nghiệp vụ chuyển giữa các ví để ghi đồng thời hai phần.'; end if;
    end if;
    if checkpoint.id is not null and new.transaction_date::date < (checkpoint.confirmed_at at time zone 'Asia/Bangkok')::date then
      raise exception 'Không được ghi lùi ngày trước mốc đối soát đã khóa.';
    end if;
  end if;
  -- Incoming funds can repair an unreconciled legacy ledger. Once reconciled,
  -- every edit/delete and outgoing posting must preserve both nonnegative wallets.
  if checkpoint.id is not null or tg_op = 'DELETE' or tg_op = 'UPDATE' or new.type = 'expense' then
    perform public.wallet_check_result();
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_pwa_guard_sepay_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous_records jsonb := '[]'::jsonb; next_records jsonb; payment jsonb; old_sum numeric; next_sum numeric;
begin
  if coalesce(auth.role(),'')='service_role' then return new;end if;
  if tg_op='UPDATE' then previous_records:=coalesce(old.payment_records,'[]'::jsonb);end if;
  next_records:=coalesce(new.payment_records,'[]'::jsonb);
  if jsonb_typeof(next_records)<>'array' or jsonb_typeof(previous_records)<>'array' then raise exception 'Invalid payment history.' using errcode='22023';end if;
  for payment in select r from jsonb_array_elements(previous_records) r where lower(btrim(coalesce(r->>'source','')))='sepay' loop
    if not exists(select 1 from jsonb_array_elements(next_records) n where n=payment) then raise exception 'Verified SePay history is immutable.' using errcode='22023';end if;
  end loop;
  for payment in select r from jsonb_array_elements(next_records) r where lower(btrim(coalesce(r->>'source','')))='sepay' loop
    if exists(select 1 from jsonb_array_elements(previous_records) p where p=payment) then continue;end if;
    if not exists(select 1 from public.payment_events e where e.invoice_id=new.id and lower(btrim(coalesce(e.source,'')))='sepay'
      and e.amount=(payment->>'amount')::numeric and e.payment_method=payment->>'payment_method'
      and e.payment_date::text=payment->>'payment_date'
      and e.external_id is not distinct from nullif(payment->>'external_id','')
      and e.external_ref is not distinct from nullif(payment->>'external_ref','')) then raise exception 'SePay record must originate from the verified payment ledger.' using errcode='22023';end if;
    if (select count(*) from jsonb_array_elements(next_records) n where n->>'external_id'=payment->>'external_id' or (nullif(payment->>'external_ref','') is not null and n->>'external_ref'=payment->>'external_ref'))>1 then raise exception 'Bank transaction cannot be appended twice.' using errcode='22023';end if;
  end loop;
  if tg_op='UPDATE' and exists(select 1 from jsonb_array_elements(previous_records||next_records) p where lower(btrim(coalesce(p->>'source','')))='sepay') then
    select coalesce(sum((p->>'amount')::numeric),0) into old_sum from jsonb_array_elements(previous_records) p;
    select coalesce(sum((p->>'amount')::numeric),0) into next_sum from jsonb_array_elements(next_records) p;
    if coalesce(new.paid_amount,0)-coalesce(old.paid_amount,0)<>next_sum-old_sum then raise exception 'Paid amount must match the payment-history change.' using errcode='22023';end if;
  end if;
  return new;
end;
$function$

