CREATE OR REPLACE FUNCTION public.guard_tenant_cycle_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts%rowtype;
begin
 if coalesce(new.billing_reason,'') not in ('monthly','first_month','room_cycle') and not coalesce(new.is_first_month,false) then return new;end if;
 perform pg_advisory_xact_lock(20261005,120000);
 select * into c from contracts where room_id=new.room_id and tenant_id=new.tenant_id and status='active' order by created_at desc limit 1;
 if c.id is null or not exists(select 1 from tenant_payment_cycles where contract_id=c.id and extract(month from period)=new.month and extract(year from period)=new.year) then return new;end if;
 if exists(select 1 from invoices i where i.room_id=new.room_id and i.tenant_id=new.tenant_id
  and (i.web_contract_id=c.id or (i.web_contract_id is null and i.created_at>=c.created_at))
  and i.month=new.month and i.year=new.year and i.payment_status not in ('cancelled','merged')
  and (i.billing_reason in ('monthly','first_month','room_cycle') or i.is_first_month)) then raise exception 'Kỳ này đã có hóa đơn cho hợp đồng hiện tại.';end if;
 new.web_contract_id:=c.id;return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_billing_period_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  room_row public.rooms%rowtype;
begin
  if coalesce(new.billing_reason, '') not in ('monthly', 'room_cycle') then
    return new;
  end if;

  select * into room_row from public.rooms where id = new.room_id for update;
  if not found then raise exception 'Không tìm thấy phòng lập hóa đơn.'; end if;
  if room_row.electric_new is distinct from new.electric_old
     or room_row.water_new is distinct from new.water_old then
    raise exception 'Chỉ số đầu kỳ không khớp phòng. Vui lòng tải lại trước khi lập hóa đơn.';
  end if;

  if exists (
    select 1 from public.invoices previous
    where previous.room_id = new.room_id and previous.tenant_id = new.tenant_id
      and previous.payment_status in ('unpaid', 'partial')
      and previous.total_amount > previous.paid_amount
      and previous.debt_confirmed_at is null
      and (coalesce(previous.billing_reason, '') in ('first_month', 'monthly', 'room_cycle')
           or previous.is_first_month is true)
      and (previous.year, previous.month) < (new.year, new.month)
  ) then
    raise exception 'Còn hóa đơn kỳ trước chưa chốt nợ. Hãy xác nhận trước khi lập kỳ mới.';
  end if;

  if exists (
    select 1 from public.invoices later
    where later.room_id = new.room_id and later.tenant_id = new.tenant_id
      and later.payment_status not in ('cancelled', 'merged')
      and (coalesce(later.billing_reason, '') in ('first_month', 'monthly', 'room_cycle')
           or later.is_first_month is true)
      and (later.year, later.month) > (new.year, new.month)
  ) then
    raise exception 'Đã có hóa đơn kỳ sau. Không thể lập lùi kỳ điện nước.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.capture_server_invoice_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare rec jsonb; previous jsonb:='[]'; room_name text; started timestamptz;
begin
 select enabled_at into started from email_automation_settings where enabled;
 if started is null then return new; end if;
 select name into room_name from rooms where id=new.room_id;
 if tg_op='INSERT' and new.payment_status not in ('cancelled','merged','paid') and new.total_amount>new.paid_amount then
  perform enqueue_server_email('invoices_services',new.id,jsonb_build_object('invoiceId',new.id,'roomId',new.room_id));
 end if;
 if tg_op='UPDATE' then previous:=coalesce(old.payment_records,'[]'); end if;
 for rec in select value from jsonb_array_elements(coalesce(new.payment_records,'[]')) loop
  if rec->>'source'='sepay' and (rec->>'amount')::numeric>0
   and nullif(rec->>'created_at','')::timestamptz>=started
   and nullif(coalesce(rec->>'external_ref',rec->>'external_id'),'') is not null
   and not exists(select 1 from jsonb_array_elements(previous) p where p->>'id'=rec->>'id') then
   perform enqueue_server_email('sepay_matched',regexp_replace(upper(coalesce(rec->>'external_ref',rec->>'external_id')),'[^A-Z0-9]','','g'),
    jsonb_build_object('invoiceId',new.id,'roomId',new.room_id,'roomName',room_name,
     'invoice',to_jsonb(new),'record',rec,'transactionKey',coalesce(rec->>'external_ref',rec->>'external_id')));
  end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.sync_tenant_paid_readings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts%rowtype;
begin
 if new.payment_status='paid' and old.payment_status is distinct from 'paid' and new.web_contract_id is not null
 and new.billing_reason='monthly' and not coalesce(new.is_settlement,false) then
  select * into c from contracts where id=new.web_contract_id and status='active' and room_id=new.room_id and tenant_id=new.tenant_id;
  if c.id is not null then
   -- An older invoice paid later must never rewind the current meter.
   update rooms set electric_old=greatest(coalesce(electric_old,0),new.electric_new),electric_new=greatest(coalesce(electric_new,0),new.electric_new),
    water_old=greatest(coalesce(water_old,0),new.water_new),water_new=greatest(coalesce(water_new,0),new.water_new)
   where id=c.room_id and status='occupied';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.wallet_guard_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  checkpoint public.wallet_reconciliations%rowtype;
  old_records jsonb := '[]'::jsonb;
  new_records jsonb := '[]'::jsonb;
  record jsonb;
  n integer;
  had_frozen boolean := false;
begin
  select * into checkpoint from public.wallet_reconciliations limit 1;
  if tg_op <> 'INSERT' then
    old_records := coalesce(old.payment_records, '[]'::jsonb);
    select exists(select 1 from jsonb_array_elements(old_records) p
      where ('invoice-' || old.id || '-' || (p->>'id')) = any(checkpoint.entry_ids)) into had_frozen;
  end if;
  if tg_op = 'DELETE' then
    if had_frozen then raise exception 'Lịch sử thanh toán trước mốc đối soát đã khóa.'; end if;
  else
    new_records := coalesce(new.payment_records, '[]'::jsonb);
    if jsonb_typeof(new_records) <> 'array' then raise exception 'Lịch sử thanh toán không hợp lệ.'; end if;
    if tg_op = 'UPDATE' then
      if new.id is distinct from old.id then raise exception 'Không được đổi mã hóa đơn.'; end if;
      if had_frozen and (
        new.payment_status in ('cancelled', 'merged')
        or (old.payment_status in ('cancelled', 'merged') and new.payment_status is distinct from old.payment_status)
        or jsonb_array_length(new_records) < jsonb_array_length(old_records)
        or exists(select 1 from jsonb_array_elements(old_records) with ordinality p(value, idx)
          where p.value is distinct from new_records->(p.idx::integer - 1))
        or new.total_amount is distinct from old.total_amount
      ) then raise exception 'Lịch sử thanh toán trước mốc đối soát đã khóa; chỉ được ghi thêm thanh toán mới.'; end if;
    end if;
    -- Validate all newly added/changed records, not just the official payment RPC.
    n := 0;
    for record in select value from jsonb_array_elements(new_records) loop
      if tg_op = 'INSERT' or record is distinct from old_records->n then
        if record->>'id' is null or record->>'payment_method' is null
          or record->>'payment_method' not in ('cash', 'transfer') or coalesce((record->>'amount')::bigint, 0) = 0 then
          raise exception 'Thanh toán phải có mã, số tiền và một ví hợp lệ.';
        end if;
        if checkpoint.id is not null then
          if (record->>'payment_date') is null
            or (record->>'payment_date')::date < (checkpoint.confirmed_at at time zone 'Asia/Bangkok')::date
            or exists(select 1 from public.wallet_reconciliations r
              where ('invoice-' || new.id || '-' || (record->>'id')) = any(r.entry_ids)) then
            raise exception 'Không được ghi lại thanh toán hoặc ghi lùi trước mốc đối soát.';
          end if;
        end if;
      end if;
      n := n + 1;
    end loop;
    if exists(select 1 from jsonb_array_elements(new_records) p group by p->>'id' having count(*) > 1) then
      raise exception 'Mã thanh toán không được trùng.';
    end if;
  end if;
  if checkpoint.id is not null or old_records is distinct from new_records then perform public.wallet_check_result(); end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_pwa_guard_sepay_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare verified public.sepay_server_transactions%rowtype; matches text[];
begin
  if lower(btrim(coalesce(new.source,'')))<>'sepay' or coalesce(auth.role(),'')='service_role' then return new;end if;
  if not exists(select 1 from public.users u where u.id=auth.uid() and u.role='admin' and u.status='active') then raise exception 'Only verified bank reconciliation can record SePay.' using errcode='42501';end if;
  -- Legacy Electron may still call the atomic RPC, but only against a real
  -- server-observed bank record, with the exact amount and target transfer code.
  select * into verified from public.sepay_server_transactions t where t.external_id=new.external_id and (new.external_ref is null or new.external_ref=t.reference_number);
  if not found or verified.status='recorded' or verified.amount<>new.amount or new.payment_method<>'transfer' then raise exception 'SePay bank provenance is missing or inconsistent.' using errcode='22023';end if;
  select array_agg(i.id) into matches from public.invoices i join public.rooms r on r.id=i.room_id where i.payment_status not in ('cancelled','merged')
    and position('P'||coalesce(nullif(regexp_replace(r.name,'\D','','g'),''),nullif(left(regexp_replace(upper(r.name),'[^A-Z0-9]','','g'),6),''),'XX')||'T'||lpad(i.month::text,2,'0')||i.year||'C'||right(regexp_replace(upper(i.id),'[^A-Z0-9]','','g'),12) in regexp_replace(upper(verified.content),'[^A-Z0-9]','','g'))>0;
  if coalesce(cardinality(matches),0)<>1 or matches[1]<>new.invoice_id then raise exception 'Bank transfer does not uniquely identify this invoice.' using errcode='22023';end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.contract_capture_usage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r jsonb; cid text; room_key text; tenant_key text; used boolean;
begin
 for r in select value from jsonb_array_elements(case when tg_op='UPDATE' and tg_table_name<>'rooms' then jsonb_build_array(to_jsonb(old),to_jsonb(new)) when tg_op='DELETE' then jsonb_build_array(to_jsonb(old)) else jsonb_build_array(to_jsonb(new)) end) loop
 room_key:=r->>'room_id'; tenant_key:=r->>'tenant_id';
 used:=case tg_table_name
  when 'invoices' then coalesce((r->>'paid_amount')::numeric,0)>0 or coalesce((r->>'deposit_applied')::numeric,0)>0 or coalesce(nullif(r->'payment_records','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb or r->>'payment_date' is not null or coalesce((r->>'electric_usage')::numeric,0)>0 or coalesce((r->>'water_usage')::numeric,0)>0
  when 'move_in_receipts' then r->>'payment_status'='paid' or r->>'payment_date' is not null
  when 'cash_transactions' then coalesce((r->>'amount')::numeric,0)<>0
  when 'payment_events' then coalesce((r->>'amount')::numeric,0)<>0
  when 'asset_snapshots' then true
  when 'rooms' then (r->'electric_old',r->'electric_new',r->'water_old',r->'water_new') is distinct from (to_jsonb(old)->'electric_old',to_jsonb(old)->'electric_new',to_jsonb(old)->'water_old',to_jsonb(old)->'water_new')
  else true end;
 if tg_table_name='rooms' then room_key:=r->>'id'; end if;
 if tg_table_name='payment_events' then select room_id,tenant_id into room_key,tenant_key from invoices where id=r->>'invoice_id'; end if;
 -- Reject stale operations that acquire a table lock after cancellation commits.
 if tg_op<>'DELETE' and (tg_op='INSERT' or used) and
  (exists(select 1 from contracts where id=r->>'contract_id' and status='cancelled') or
   tenant_key is not null and room_key is not null and not exists(select 1 from contracts where room_id=room_key and tenant_id=tenant_key and status='active') and
   (select status='cancelled' from contracts where room_id=room_key and tenant_id=tenant_key order by created_at desc,id desc limit 1)) then
  raise exception 'Hợp đồng đã hủy. Không được ghi thêm thanh toán, hóa đơn hoặc bàn giao cho hợp đồng này.';
 end if;
 if used then
  for cid in select c.id from contracts c where c.status='active' and c.original_confirmed_at is not null and
   (c.id=r->>'contract_id' or c.room_id=room_key and (tenant_key is null or c.tenant_id=tenant_key)) loop
   insert into contract_usage_evidence(contract_id,source_table,source_id) values(cid,tg_table_name,r->>'id') on conflict do nothing;
  end loop;
 end if;
 end loop;
 if tg_op='DELETE' then return old; else return new; end if;
end $function$

